_SCAN_OP_RANGE = (2554, 20623)


def scan_phase(n_chunks: int = IMAGE_CHUNK_COUNT) -> Phase:
    """The scan phase for n_chunks image-data reads: the captured head
    (slope tables, scan register batch with the line-count injection,
    execute), n_chunks x (descriptor + IMAGE_BLOCK_OPS), the captured
    tail. Line count to program = n_chunks * LINES_PER_CHUNK."""
    ops = list(_scan_head)
    for i in range(n_chunks):
        wi = IMAGE_DESC_WI_FIRST if i == 0 else IMAGE_DESC_WI_REST
        ops.append(Op("cw", IMAGE_DESC_DT, bm=0x40, br=0x04, wv=0x0082, wi=wi, data=IMAGE_DESC_DATA))
        ops.extend(IMAGE_BLOCK_OPS)
    ops.extend(_scan_tail)
    return Phase(name="scan", op_range=_SCAN_OP_RANGE, ops=ops, injections=_SCAN_INJECTIONS)


